#!/bin/bash
# Key-length sweep ("UUID Bit" experiment).
#
# Real ruler niah_single_3 4k documents with ONLY the key swapped for an N-bit
# random-hex key (generated by experiments/make_keylen_data.py -> data/keylen/).
# Everything else (haystack, needle sentence, keyword, question) is held fixed, so
# the single independent variable is key entropy in bits. Measures f(N): the cache
# budget at which an N-bit key stops being recalled losslessly.
#
# One pass gives BOTH accuracy (AM generation vs gold) AND gold perplexity
# (teacher-forced key under the AM cache / full ctx / no ctx).
#
# Env overrides:
#   BITS=16|32|64|96          (which key-length dataset: data/keylen/keylen_${BITS}.jsonl)
#   TARGET_SIZE=0.25|0.125|0.0625   (4x / 8x / 16x)
#   N=<#docs>                 (default 50)
set -eo pipefail

BITS="${BITS:-16}"
TARGET_SIZE="${TARGET_SIZE:-0.25}"     # 0.25 = 4x, 0.125 = 8x, 0.0625 = 16x
N="${N:-50}"
MAXLEN="${MAXLEN:-16384}"              # 4k context, RoPE headroom
CACHE_STORE="${CACHE_STORE:-}"

case "$TARGET_SIZE" in
  0.25)   RATIO=4x ;;
  0.125)  RATIO=8x ;;
  0.0625) RATIO=16x ;;
  *)      RATIO="ts${TARGET_SIZE}" ;;
esac

cd "$(dirname "$0")/../official"

echo "=== keylen sweep: ${BITS}-bit key, 4k, ${RATIO}  (n=${N}) ==="
python -u -m evaluation.run_qa_evaluation \
  --model-name Qwen/Qwen3-4B-Instruct-2507 \
  --dataset-name "keylen_${BITS}" \
  --n-articles "${N}" --start-article 0 \
  --log-dir "../results/keylen/${BITS}bit/${RATIO}" --name "keylen_${BITS}" \
  --max-model-len "${MAXLEN}" \
  --max-new-tokens 128 \
  --methods highest_attn_keys_rms_nnls2_-3_3_lsq_on-policy \
  --target-size "${TARGET_SIZE}" \
  --query-config repeat \
  --algorithm-config best \
  --precomputed-budget-path head_budget_optimization/head_budgets/Qwen3-4B-Instruct-2507/optimized_agnostic.json \
  --max-ratio-per-head 0.95 \
  --compute-perplexity 0 \
  --compute-gold-perplexity 1 \
  --compute-stats 0 \
  --cache-store-dir "${CACHE_STORE}"
